    if (!['linear', 'nearest', 'exact'].includes(c.temperatureRule)) p.push('Choose how temperatures between rows are handled.');
    if (!Array.isArray(c.rows) || c.rows.some((r) => !Array.isArray(r) || r.length !== 2 || !r.every(Number.isFinite))) p.push('CPO conversion rows must be pairs of numbers (temperature, value).');
