      if ((lo === null) !== (hi === null)) p.push(`Set both lower and upper variance limits for ${prod}, or leave both blank.`);
      else if (lo !== null && !(Number.isFinite(lo) && Number.isFinite(hi) && lo <= hi)) p.push(`Variance limits for ${prod}: lower must be less than or equal to upper.`);
