    for (const t of DATA_TABLES) if (!Array.isArray(b.tables[t])) p.push(`Missing table "${t}".`);
    if (backupUsers && !Array.isArray(b.tables[usersTable])) p.push(`Missing table "${usersTable}". This backup cannot restore user accounts.`);
    if (p.length) return p;
    if ((await sha256(JSON.stringify(b.tables))) !== b.checksum) p.push('Checksum does not match: the file has been changed or is damaged.');
    for (const t of backupTables) {
      const cols = new Set(await db.columns(t));
      for (const row of b.tables[t]) for (const c of Object.keys(row)) if (!cols.has(c)) { p.push(`Unknown column "${c}" in table "${t}".`); break; }
    }
    if (backupUsers && !b.tables[usersTable].some((u) => u.role === 'admin' && u.active)) p.push('Backup has no active Admin user.');
    for (const a of b.tables.audits) {
      try { J(a.inputs); if (a.status !== 'draft') { const s = J(a.snapshot); if (!s || !s.results) throw new Error(); } } catch { p.push(`Audit ${a.reference} rev ${a.revision} has damaged data.`); }
    }
    for (const t of b.tables.calibration_tables) { try { const d = J(t.data); if (!Array.isArray(d.rows)) throw new Error(); } catch { p.push(`Calibration table ${t.unit_code} v${t.version} has damaged data.`); } }
    for (const u of UNITS) if (!b.tables.calibration_tables.some((t) => t.unit_code === u.code && t.is_active)) p.push(`No active calibration table for ${u.name}.`);
